'use strict';
const KEY='cookie-season-concept-v1', $=s=>document.querySelector(s);
const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2}), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const NAV=[['overview','◫','Overview'],['requests','▤','Requests & people'],['bake','♧','Bake plan'],['shopping','▧','Shopping list'],['recipes','◈','Recipes'],['ingredients','▦','Ingredients & pantry'],['settings','⚙','Kitchen settings']];
let view='overview',query='',filter='All',shopOnly=false;
function seed(){
 const data=structuredClone(window.SOURCE_DATA);
 data.recipes.forEach(r=>r.lines.forEach(l=>{const i=data.ingredients.find(i=>i.id===l.ingredientId);l.canonicalAmount=l.packagesPerBatch*i.unitsPerPackage;}));
 data.ingredients.forEach((i,n)=>{i.price=null;i.priceKind='Missing';i.pantry=0;});
 data.season=new Date().getFullYear();
 data.requests=[];
 data.sampleRequestsCleared=true;
 data.recipes.forEach(r=>r.baked=0);
 return data;
}
let state;
try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}
// Expand the original sample without overwriting browser edits or changing request IDs.
for(const i of window.SOURCE_DATA.ingredients)if(!state.ingredients.some(x=>x.id===i.id))state.ingredients.push(structuredClone(i));
for(const r of window.SOURCE_DATA.recipes)if(!state.recipes.some(x=>x.id===r.id))state.recipes.push(structuredClone(r));
state.recipes.forEach(r=>{if(r.name==='Caramal Cups')r.name='Caramel Cups';});
CookieEngine.upgradeState(state,window.SOURCE_DATA);
if(!state.sampleRequestsCleared){
 state.requests=state.requests.filter(o=>!/^demo-\d+$/.test(o.id)&&o.id!=='kitchen');
 if(!state.requests.length)state.recipes.forEach(r=>r.baked=0);
 state.sampleRequestsCleared=true;
 try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}
}
let plan=CookieEngine.calculate(state);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable; changes last only for this visit.');}plan=CookieEngine.calculate(state);}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function go(v){view=v;query='';filter='All';location.hash=v;render();window.scrollTo({top:0,behavior:'smooth'});}
function cookie(n=0){const colors=['#d8b46e','#8d6747','#bd8749','#d4b58d','#74523e','#ead499','#cba66c','#e4d5ae'];return `<svg viewBox="0 0 140 140" aria-hidden="true"><circle cx="70" cy="72" r="56" fill="${colors[n%8]}" stroke="#b59058" stroke-width="3"/><path d="M30 53Q55 15 98 39M24 82Q28 106 52 115" fill="none" stroke="#f4dfad" stroke-width="5" opacity=".5"/>${[[47,45],[83,35],[101,67],[69,71],[43,92],[88,103],[31,66],[105,93]].map(([x,y],i)=>`<ellipse cx="${x}" cy="${y}" rx="${n===5||n===7?3:5}" ry="${n===5||n===7?2:4}" fill="${n===5||n===7?'#fff4da':'#604332'}" transform="rotate(${i*22} ${x} ${y})"/>`).join('')}</svg>`;}
function art(){return `<svg viewBox="0 0 230 180" aria-hidden="true"><ellipse cx="116" cy="98" rx="101" ry="67" fill="#fafaf1" stroke="#d3dcc5" stroke-width="3"/><ellipse cx="116" cy="98" rx="87" ry="54" fill="#f3f3e6"/>${[[60,47,0],[117,25,5],[135,76,4],[76,96,7]].map(([x,y,n])=>`<g transform="translate(${x-28} ${y-17}) scale(.58)">${cookie(n).replace(/<svg[^>]*>|<\/svg>/g,'')}</g>`).join('')}<path d="M169 12l7 10 12-6M32 130l-14 8m16-1-5 14" stroke="#8b9b6d" fill="none" stroke-width="3"/></svg>`;}
function head(eyebrow,title,sub,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="page-buttons">${buttons}</div></div>`;}
function metrics(items){const destinations=view==='overview'?['requests','bake','shopping','bake']:[];return `<div class="metric-grid">${items.map(([label,val,note],index)=>{const target=destinations[index];return `<${target?'button type="button"':'div'} class="metric ${target?'metric-link':''}" ${target?`data-go="${target}" aria-label="${esc(label)}: open ${target==='requests'?'requests':target==='shopping'?'shopping list':'bake plan'}"`:''}><div class="metric-label">${label}${target?'<span aria-hidden="true">↗</span>':''}</div><div class="metric-value">${val}</div><div class="metric-note">${note}</div></${target?'button':'div'}>`;}).join('')}</div>`;}
function status(s){return `<span class="status ${s==='Pending'?'pending':s==='Packed'||s==='Handed over'?'packed':''}">${esc(s)}</span>`;}
function notice(){return `<div class="notice"><strong>Planning preview.</strong> Starting prices are illustrative, not current store quotes. Imported yields and ingredient conversions need the baker’s review before a real shopping trip.</div>`;}
function personCost(o){return Object.entries(o.items).reduce((s,[id,q])=>{const r=plan.recipePlans.find(r=>r.id===Number(id));return s+(r?r.batchCost/r.yield*q:0);},0);}
function overview(){const progress=plan.batches?Math.round(plan.baked/plan.batches*100):0;const next=plan.active.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return head('MAKE ROOM FOR THE GOOD PART','A sweeter season, a simpler plan.','Your holiday kitchen, from the first request to the last ribbon.',`<button class="btn" data-action="new">＋ Add a request</button>`)+
 `<section class="hero"><div><div class="eyebrow">HOLIDAY 2026 · YOUR SEASON AT A GLANCE</div><h2>${plan.requested?'Thousands of cookies.<br>One calm place to start.':'Your kitchen is ready.<br>Let the season begin.'}</h2><p>${plan.active.length?`You have ${fmt(plan.requested)} cookies to make for ${plan.active.length} requests. Your recipes are combined into one bake plan and one pantry-aware shopping list.`:'Review your recipes and pantry now. Your baking and shopping plans will take shape as you accept requests.'}</p><button class="btn" data-go="${plan.requested?'shopping':'recipes'}">${plan.requested?'Build my shopping plan':'Review my recipes'} <span>→</span></button></div><div class="hero-art">${art()}</div></section>`+
 metrics([['Cookies requested',fmt(plan.requested),`${fmt(plan.requested/12)} dozen · accepted requests`],['Batches to bake',fmt(plan.batches),`${fmt(plan.extra)} cookies available for community donations`],['Shopping estimate',((plan.missingPrices||plan.missingConversions||plan.issues.length)?'≥ ':'')+money(plan.spend),`${plan.missingPrices?plan.missingPrices+' prices missing':'Illustrative package prices'} · ${plan.packagesToBuy} packages`],['Baking progress',progress+'%',`${plan.baked} of ${plan.batches} planned batches recorded`]])+
 `<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>What’s on the baking list</h2><small>Accepted requests, gifts and extras combined</small></div><button class="text-link" data-go="bake">See bake plan →</button></div><div class="panel-body">${!plan.requested?'<div class="blank">No accepted requests yet. Your recipe totals will appear here.</div>':''}${plan.recipePlans.filter(r=>r.requested>0).map((r,n)=>`<div class="progress-row"><div class="progress-label"><span class="dot" style="background:${['#688567','#b9935c','#8a9b70','#b57f58'][n%4]}"></span>${esc(r.name)}</div><div class="progress-number">${fmt(r.requested)} cookies</div><div class="bar"><span style="width:${r.requested/Math.max(1,...plan.recipePlans.map(r=>r.requested))*100}%"></span></div></div>`).join('')}</div></section><div><section class="panel"><div class="panel-head"><div><h2>Ready for your attention</h2><small>Small steps that keep the season moving</small></div></div><div class="panel-body"><div class="person-row"><span class="avatar">＋</span><div class="person-info"><strong>${state.requests.filter(o=>o.status==='Pending').length} requests awaiting acceptance</strong><small>Pending requests are excluded from the plan</small></div><button class="text-link" data-go="requests">Review →</button></div><div class="person-row"><span class="avatar">✓</span><div class="person-info"><strong>${state.recipes.filter(r=>!r.reviewed).length} recipes to verify</strong><small>Confirm batch yields and recipe quantities</small></div><button class="text-link" data-go="recipes">Open →</button></div><div class="person-row"><span class="avatar">▧</span><div class="person-info"><strong>${plan.ingredientPlans.filter(i=>i.buy>0).length} ingredients on the shopping list</strong><small>Pantry stock is already deducted</small></div><button class="text-link" data-go="shopping">Plan →</button></div></div></section><section class="panel"><div class="panel-head"><div><h2>First handoffs</h2><small>One packing list for every person</small></div><button class="text-link" data-go="requests">All people →</button></div><div class="panel-body">${!next.length?'<div class="blank">No handoffs scheduled yet.</div>':''}${next.map(o=>`<div class="person-row"><span class="avatar">${esc(o.name[0])}</span><div class="person-info"><strong>${esc(o.name)}</strong><small>${date(o.date)} · ${esc(o.method)} · ${fmt(Object.values(o.items).reduce((a,b)=>a+b,0))} cookies</small></div><button class="text-link" data-person="${o.id}">Open →</button></div>`).join('')}</div></section></div></div>`+notice();}
function requests(){let orders=state.requests.filter(o=>(filter==='All'||o.status===filter)&&o.name.toLowerCase().includes(query.toLowerCase()));return head('EVERY REQUEST, EVERY PERSON','Requests','People, quantities and handoff dates.',`<button class="btn quiet" data-action="print">Print</button><button class="btn" data-action="new">＋ Add a request</button>`)+
 `<div class="toolbar"><input class="search" id="request-search" placeholder="Search people…" aria-label="Search people" value="${esc(query)}"><div class="filters">${['All','Pending','Accepted','Packed','Handed over','Cancelled'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div></div><section class="panel table-wrap"><table><thead><tr><th>Person / household</th><th>Handoff</th><th>Request</th><th class="num">Cookies</th><th>Status</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr class="row-click" data-person="${o.id}"><td><strong>${esc(o.name)}</strong><small>${esc(o.home||'WV')} · ${esc(o.method)}</small></td><td>${date(o.date)}</td><td>${Object.keys(o.items).length} varieties<small>${Object.entries(o.items).slice(0,2).map(([id,q])=>`${fmt(q)} ${esc(state.recipes.find(r=>r.id==id).name)}`).join(' · ')}${Object.keys(o.items).length>2?'…':''}</small></td><td class="num">${fmt(Object.values(o.items).reduce((a,b)=>a+b,0))}</td><td>${status(o.status)}</td><td><button class="text-link" data-person="${o.id}">Details →</button></td></tr>`).join('')}</tbody></table>${!orders.length?`<div class="blank">${state.requests.length?'No requests match this view.':'No requests yet. Add the first one when you’re ready.'}</div>`:''}</section><p class="list-note">Only accepted, packed and handed-over requests contribute to this season’s baking and shopping totals. Pending and cancelled requests are excluded.</p>`;}
function bake(){return head('FROM REQUESTS TO REAL BATCHES','A plan for every tray.','Whole batches are combined across people before ingredients are calculated.',`<button class="btn quiet" data-action="print">Print bake plan</button><button class="btn" data-go="shopping">Shopping list →</button>`)+metrics([['Requested',fmt(plan.requested),'Individual cookies across accepted requests'],['Planned production',fmt(plan.produced),'Based on whole batches per recipe'],['For community donations',fmt(plan.extra),'Full-batch surplus · schools and service personnel'],['Ingredient use',((plan.missingPrices||plan.missingConversions||plan.issues.length)?'≥ ':'')+money(plan.usedCost),'Cost of ingredients consumed · illustrative']])+notice()+`<section class="panel table-wrap"><table><thead><tr><th>Recipe</th><th class="num">Requested</th><th class="num">Yield / batch</th><th class="num">Batches</th><th class="num">Make</th><th class="num">For donation</th><th class="num">Batches baked</th></tr></thead><tbody>${plan.recipePlans.filter(r=>r.requested>0).map(r=>`<tr><td><button class="text-link" style="padding:0;font-size:12px" data-recipe="${r.id}"><strong>${esc(r.name)} ↗</strong></button><small>${r.reviewed?'Recipe reviewed':'Yield and quantities need review'}</small></td><td class="num">${fmt(r.requested)}</td><td class="num">${fmt(r.yield)}</td><td class="num"><strong>${r.batches}</strong></td><td class="num">${fmt(r.produced)}</td><td class="num">${fmt(r.extra)}</td><td class="num"><input class="inline-input" type="number" min="0" max="${r.batches}" step="1" value="${Math.min(r.baked,r.batches)}" data-baked="${r.id}" aria-label="Batches baked for ${esc(r.name)}"></td></tr>`).join('')}</tbody></table><div class="table-total"><span><strong>Season total</strong> · ${fmt(plan.batches)} batches</span><span>${fmt(plan.produced)} cookies planned · ${fmt(plan.extra)} available for donation</span></div></section><div class="panel"><div class="panel-body"><h2 class="section-title">Full batches. A little more to give.</h2><p class="list-note">Whole batches are intentional: the cookies beyond individual requests are available for schools, emergency response personnel, and service personnel. This donation surplus is shown by recipe so it can be packed for those recipients. Ingredients and ingredient-use cost include every cookie in the full batches. Donation destinations have not yet been assigned in this concept. Recording baked batches tracks progress; it does not remove ingredients from the shopping plan. Update pantry stock after shopping to reflect what you have available for the season.</p></div></div>`;}
function shopping(){const rows=plan.ingredientPlans.filter(i=>!shopOnly||i.buy>0||i.incomplete).slice().sort((a,b)=>a.name.localeCompare(b.name));return head('ONE LIST. FEWER STORE RUNS.','Shop once. Bake with confidence.','Every recipe combined, your pantry deducted, and package quantities rounded up.',`<button class="btn quiet" data-action="new-ingredient">＋ Add ingredient</button><button class="btn quiet" data-go="ingredients">Manage packages & pantry</button><button class="btn quiet" data-action="csv">Export list</button><button class="btn" data-action="print">Print shopping list</button>`)+metrics([['Ingredients needed',plan.ingredientPlans.length,'Shared ingredients consolidated'],['Packages to buy',fmt(plan.packagesToBuy),'Rounded after combining all recipes'],['Shopping estimate',((plan.missingPrices||plan.missingConversions||plan.issues.length)?'≥ ':'')+money(plan.spend),plan.missingPrices?`${plan.missingPrices} ingredients have no price`:'Illustrative prices · whole packages'],['Ingredient use',((plan.missingPrices||plan.missingConversions||plan.issues.length)?'≥ ':'')+money(plan.usedCost),'Includes ingredients already in your pantry']])+notice()+`<div class="toolbar"><span class="list-note">Pantry amounts are available <strong>packages at the start of this plan</strong>; partial packages are welcome.</span><label class="switch-label"><input class="check" type="checkbox" id="shop-only" ${shopOnly?'checked':''}> Only show items to buy</label></div><section class="panel table-wrap"><table><thead><tr><th>Ingredient / package</th><th class="num">Need</th><th class="num">Have (packages)</th><th class="num">Buy (packages)</th><th class="num">Price / package</th><th class="num">Spend</th></tr></thead><tbody>${rows.map(i=>`<tr><td><button class="text-link" style="padding:0;font-size:12px" data-ingredient="${i.id}"><strong>${esc(i.name)} ↗</strong></button><small>${esc(i.package)} package · ${i.reviewed?'Conversion reviewed':'Conversion needs review'}</small></td><td class="num">${i.incomplete?'<span class="alert-number">Conversion needed</span>':fmt(i.amount)+' '+esc(i.unit)}<small>${i.packages==null?'Quantity not yet determined':fmt(i.packages)+' packages'}</small></td><td class="num"><input class="inline-input" type="number" min="0" step="any" value="${i.pantry}" data-pantry="${i.id}" aria-label="Pantry packages of ${esc(i.name)}"></td><td class="num"><strong>${i.buy==null?'—':i.buy}</strong></td><td class="num"><input class="inline-input price-input" type="number" min="0" step="0.01" value="${i.price??''}" placeholder="Needed" data-price="${i.id}" aria-label="Price per package of ${esc(i.name)}"><small>${i.priceKind==='Manual'?esc(i.priceDate):i.priceKind==='Illustrative'?'Illustrative price':'Price needed'}</small></td><td class="num">${i.incomplete?'<span class="alert-number">Conversion needed</span>':i.spend==null?'<span class="alert-number">Price needed</span>':money(i.spend)}</td></tr>`).join('')}</tbody></table><div class="table-total"><span>${fmt(plan.packagesToBuy)} packages to buy · ${plan.missingPrices} missing prices</span><strong>${(plan.missingPrices||plan.missingConversions)?'Known subtotal: ':'Estimated shopping spend: '}${money(plan.spend)}</strong></div></section><p class="list-note">This estimate covers ingredients. Packaging, shipping and taxes are not included. Changing a price updates costs everywhere; clearing a price marks it missing rather than assuming it is free. Ingredient names open a breakdown by recipe and package conversion settings.</p>`;}
function recipes(){return head('YOUR RECIPES, YOUR NUMBERS','The heart of your holiday kitchen.','All 38 catalog recipes from v18. Confirm the details with the baker.',`<button class="btn quiet" data-go="shopping">Edit ingredient prices →</button>`)+notice()+`<div class="toolbar"><input class="search" id="recipe-search" placeholder="Search all 38 recipes…" aria-label="Search recipes" value="${esc(query)}"><span class="list-note">38 catalog recipes · 1 unmatched source entry</span></div><div class="cards">${plan.recipePlans.filter(r=>r.name.toLowerCase().includes(query.toLowerCase())).slice().sort((a,b)=>a.name.localeCompare(b.name)).map((r,n)=>`<button class="recipe-card" data-recipe="${r.id}"><div class="recipe-art" style="background:${['#e8eddf','#efe9df','#ece5d9','#f1e9e0'][n%4]}">${cookie(n)}</div><div class="recipe-body"><div class="eyebrow" style="font-size:8px">THE FAMILY RECIPE COLLECTION</div><h3>${esc(r.name)}</h3><div class="recipe-meta"><span>${r.yield} cookies / batch</span><span>${r.missing?'Incomplete cost':money(r.batchCost)+' / batch'}</span></div>${status(r.reviewed?'Reviewed':'Needs review')}</div></button>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-body"><h2 class="section-title">One source entry needs clarification</h2><p class="list-note">The workbook also contains a separate four-ingredient “Choc Chip Toffee Bars” entry without a matched batch yield. It differs from “Chocolate Chip Toffee Bars.” It is retained for review and excluded from requests and totals.</p><button class="btn quiet small" data-action="orphan">Review unmatched entry →</button></div></section><p class="list-note">Recipe quantities and yields come from the historical workbook. Package conversions are also imported assumptions. This concept does not include baking instructions; those can be added with the baker. Prices are illustrative and editable.</p><button class="text-link" data-action="reset">Reset this browser’s demonstration data</button>`;}
function quantityControl(name,value,max,label,guest=false){return `<span class="quantity-control"><button type="button" data-quantity-step="-1" aria-label="Decrease ${esc(label)}">−</button><input class="inline-input ${guest?'guest-qty':''}" name="${name}" type="number" inputmode="numeric" min="0" max="${max}" step="1" value="${value}" ${guest?'readonly':''} aria-label="${esc(label)}"><button type="button" data-quantity-step="1" aria-label="Increase ${esc(label)}">+</button></span>`;}
function render(){plan=CookieEngine.calculate(state);$('#nav').innerHTML=NAV.map(([v,i,n])=>`<button data-go="${v}" class="${view===v?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#main').innerHTML=({overview,requests,bake,shopping,recipes}[view]||overview)();if(view==='guest')$('#guest-form').addEventListener('submit',submitGuest);}
function modal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();}
function modalHead(title,sub){return `<div class="modal-head"><div><h2>${esc(title)}</h2><p class="subtitle">${sub}</p></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`;}
function openPerson(id){const o=state.requests.find(o=>o.id===id);if(!o)return;const count=Object.values(o.items).reduce((a,b)=>a+b,0);const missing=Object.keys(o.items).some(id=>plan.recipePlans.find(r=>r.id==id).missing);modal(modalHead(o.name,`${date(o.date)} · ${esc(o.method)} · ${status(o.status)}`)+`<div class="modal-body"><div class="packing-total">${fmt(count)} cookies · ${fmt(count/12)} dozen</div><p class="list-note">Packing checklist · estimated ingredients allocated to this request: ${missing?'≥ ':''}${money(personCost(o))}${missing?' (incomplete prices)':''}. Cookies available for community donations are shown separately in the bake plan.</p>${o.note?`<div class="notice">${esc(o.note)}</div>`:''}<ul class="checklist">${Object.entries(o.items).map(([rid,q])=>`<li><input class="check" type="checkbox" data-pack="${o.id}" data-rid="${rid}" ${o.packed?.[rid]?'checked':''} aria-label="Packed ${esc(state.recipes.find(r=>r.id==rid).name)}"><span>${esc(state.recipes.find(r=>r.id==rid).name)}</span><b>${fmt(q)}</b></li>`).join('')}</ul><label class="field">Request status<select data-status="${o.id}">${['Pending','Accepted','Packed','Handed over','Cancelled'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="modal-actions"><button class="btn quiet" data-action="print">Print packing list</button><button class="btn quiet" data-edit="${o.id}">Edit quantities</button><button class="btn" data-action="close">Done</button></div></div>`);}
function openRequest(id){const o=state.requests.find(o=>o.id===id);modal(modalHead(o?'Edit request':'Add a request','Enter individual cookies. All totals recalculate when you save.')+`<form class="modal-body" id="request-form"><div class="form-grid"><label class="field">Name / household<input name="name" required maxlength="100" value="${esc(o?.name||'')}"></label><label class="field">Handoff date<input name="date" type="date" required value="${o?.date||state.season+'-12-20'}"></label><label class="field">Home<select name="home">${['WV','OH'].map(h=>`<option ${h===(o?.home||'WV')?'selected':''}>${h}</option>`).join('')}</select></label><label class="field">Handoff<select name="method">${['Pickup','Delivery','Shipping','Gifts'].map(m=>`<option ${m===o?.method?'selected':''}>${m}</option>`).join('')}</select></label><label class="field">Status<select name="status">${['Pending','Accepted','Packed','Cancelled'].map(s=>`<option ${s===(o?.status||'Accepted')?'selected':''}>${s}</option>`).join('')}</select></label></div>${state.recipes.filter(r=>!r.archived||o?.items[r.id]>0).map(r=>`<div class="request-cookie"><strong>${esc(r.name)}${r.archived?' (archived)':''}</strong>${quantityControl("r-"+r.id,o?.items[r.id]||0,100000,"Cookies of "+r.name)}<span style="font-size:10px">cookies</span></div>`).join('')}<label class="field" style="margin-top:18px">Notes<textarea name="note" maxlength="1000">${esc(o?.note||'')}</textarea></label><div class="modal-actions"><button class="btn quiet" type="button" data-action="close">Cancel</button><button class="btn" type="submit">Save request</button></div></form>`);$('#request-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),items={};state.recipes.forEach(r=>{const q=Number(f.get('r-'+r.id));if(q>0)items[r.id]=q;});if(!Object.keys(items).length){toast('Add at least one cookie to the request.');return;}if(!f.get('name').trim()){toast('Enter a name for this request.');return;}const obj={id:o?.id||crypto.randomUUID(),name:f.get('name').trim(),date:f.get('date'),home:f.get('home'),method:f.get('method'),status:f.get('status'),note:f.get('note'),items,packed:o?.packed||{}};if(o)state.requests[state.requests.indexOf(o)]=obj;else state.requests.push(obj);persist();$('#modal').close();render();toast('Request saved. Baking and shopping totals updated.');});}
function openRecipe(id){const r=state.recipes.find(r=>r.id===Number(id));modal(modalHead(r.name,'Review the imported quantities, then confirm the batch yield.')+`<form class="modal-body" id="recipe-form"><div class="notice">Quantities below use the ingredient’s common unit so they can be combined across recipes. Conversions come from the old spreadsheet and need review. Baking instructions are not yet included.</div><label class="field">Cookies produced per batch<input name="yield" type="number" min="1" max="10000" step="1" required value="${r.yield}"></label><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th class="num">Per batch</th><th>Common unit</th></tr></thead><tbody>${r.lines.map((l,n)=>{const i=state.ingredients.find(i=>i.id===l.ingredientId);return `<tr><td>${esc(i.name)}</td><td class="num"><input class="inline-input" name="l-${n}" type="number" min="0" step="any" required value="${l.canonicalAmount}" aria-label="Per batch quantity of ${esc(i.name)}"></td><td>${esc(i.unit)}</td></tr>`;}).join('')}</tbody></table></div><label class="switch-label" style="margin-top:22px"><input class="check" name="reviewed" type="checkbox" ${r.reviewed?'checked':''}> Baker has reviewed these quantities and this yield</label><div class="modal-actions"><button class="btn quiet" type="button" data-action="close">Cancel</button><button class="btn" type="submit">Save recipe</button></div></form>`);$('#recipe-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);r.yield=Number(f.get('yield'));r.lines.forEach((l,n)=>l.canonicalAmount=Number(f.get('l-'+n)));r.reviewed=f.has('reviewed');persist();r.baked=Math.min(r.baked,plan.recipePlans.find(x=>x.id===r.id).batches);persist();$('#modal').close();render();toast('Recipe saved. Batch and ingredient totals recalculated.');});}
function openIngredient(id){const i=state.ingredients.find(i=>i.id===Number(id)),p=plan.ingredientPlans.find(i=>i.id===Number(id));modal(modalHead(i.name,'See where it’s needed and verify the package conversion.')+`<form class="modal-body" id="ingredient-form"><div class="form-grid"><label class="field">Package description<input name="package" required maxlength="60" value="${esc(i.package)}"></label><label class="field">${esc(i.unit)} per package<input name="units" required type="number" min="0.000001" step="any" value="${i.unitsPerPackage}"></label></div><div class="notice">Changing the conversion changes how many packages are needed. The recipe quantities remain in ${esc(i.unit)}. Verify this ingredient’s conversion rather than using a generic cups-to-weight estimate.</div><h3 class="section-title">Used in the bake plan</h3><ul class="checklist">${(p?.uses||[]).map(u=>`<li><span>${esc(u.name)}</span><b>${fmt(u.amount)} ${esc(i.unit)}</b></li>`).join('')||'<li>Not needed by any accepted request.</li>'}</ul><label class="switch-label"><input class="check" name="reviewed" type="checkbox" ${i.reviewed?'checked':''}> Baker has verified this package conversion</label><div class="modal-actions"><button class="btn quiet" type="button" data-action="close">Cancel</button><button class="btn" type="submit">Save conversion</button></div></form>`);$('#ingredient-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);i.package=f.get('package');i.unitsPerPackage=Number(f.get('units'));i.reviewed=f.has('reviewed');persist();$('#modal').close();render();toast('Package conversion updated. Shopping quantities recalculated.');});}
function exportCSV(){const rows=[['Cookie Season — demonstration shopping list'],['Fictional requests; illustrative prices; review recipes and conversions'],['Ingredient','Package','Quantity needed','Unit','Pantry packages','Packages to buy','Price per package','Shopping spend','Price provenance'],...plan.ingredientPlans.filter(i=>i.buy>0||i.incomplete).map(i=>[i.name,i.package,i.incomplete?'Conversion needed':i.amount,i.unit,i.pantry,i.buy??'Conversion needed',i.price??'Missing',i.spend??'Incomplete',i.priceKind])];const blob=new Blob([rows.map(row=>row.map(v=>'"'+(/^[=+@\-]/.test(String(v))?"'":'')+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Cookie-Season-Shopping-List.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-go]');if(!b)return;if(b.dataset.go){if($('#modal').open)$('#modal').close();go(b.dataset.go);}else if(b.dataset.person)openPerson(b.dataset.person);else if(b.dataset.edit){$('#modal').close();openRequest(b.dataset.edit);}else if(b.dataset.recipe!=null)openRecipe(b.dataset.recipe);else if(b.dataset.ingredient!=null)openIngredient(b.dataset.ingredient);else if(b.dataset.filter){filter=b.dataset.filter;render();}else if(b.dataset.action==='orphan')openOrphan();else if(b.dataset.action==='new')openRequest();else if(b.dataset.action==='close')$('#modal').close();else if(b.dataset.action==='print')window.print();else if(b.dataset.action==='csv')exportCSV();else if(b.dataset.action==='reset'&&confirm('Reset all demonstration requests, prices and pantry changes in this browser?')){state=seed();persist();render();toast('Demonstration data restored.');}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.pantry!=null||t.dataset.price!=null){const isPrice=t.dataset.price!=null;const i=state.ingredients.find(i=>i.id===Number(isPrice?t.dataset.price:t.dataset.pantry));const v=t.value===''?null:Number(t.value);if((!isPrice&&v===null)||v!==null&&(!Number.isFinite(v)||v<0)){toast('Enter a valid amount of zero or more.');render();return;}if(isPrice){i.price=v;i.priceKind=v===null?'Missing':'Manual';i.priceDate=new Date().toLocaleDateString('en-US');}else i.pantry=v;persist();render();}else if(t.dataset.baked!=null){const r=state.recipes.find(r=>r.id===Number(t.dataset.baked)),p=plan.recipePlans.find(p=>p.id===r.id),v=Number(t.value);if(!Number.isInteger(v)||v<0||v>p.batches){toast('Baked batches must be between zero and the planned batches.');render();return;}r.baked=v;persist();render();}else if(t.dataset.status){const o=state.requests.find(o=>o.id===t.dataset.status);o.status=t.value;persist();render();}else if(t.dataset.pack){const o=state.requests.find(o=>o.id===t.dataset.pack);o.packed??={};o.packed[t.dataset.rid]=t.checked;persist();}else if(t.id==='shop-only'){shopOnly=t.checked;render();}});
document.addEventListener('input',e=>{if(['request-search','recipe-search'].includes(e.target.id)){const id=e.target.id;query=e.target.value;const pos=e.target.selectionStart;render();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos);}if(e.target.classList.contains('guest-qty')){const total=[...document.querySelectorAll('.guest-qty')].reduce((s,i)=>s+(Number(i.value)||0)*12,0);$('#guest-total').textContent=fmt(total)+' cookies';}});

window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(NAV.map(n=>n[0]).includes(v)&&v!==view){view=v;query='';filter='All';render();}});
if(NAV.map(n=>n[0]).includes(location.hash.slice(1)))view=location.hash.slice(1);
render();

function openOrphan(){const o=window.SOURCE_DATA.orphans[0];modal(modalHead(o.name,'Unmatched source entry · not included in the active catalog')+`<div class="modal-body"><div class="notice">${esc(o.note)}</div><ul class="checklist">${o.lines.map(l=>{const i=state.ingredients.find(i=>i.id===l.ingredientId);return `<li><span>${esc(i.name)}</span><b>${fmt(l.canonicalAmount)} ${esc(i.unit)}</b></li>`;}).join('')}</ul><p class="list-note">Ask the baker whether this is another recipe or a source error, and confirm its batch yield before activating it.</p><div class="modal-actions"><button class="btn" data-action="close">Done</button></div></div>`);}
